export interface SunoPrompt {
  genre: string;
  vocalStyle: string;
  instruments: string;
  productionStyle: string;
  mood: string;
  tempo: string;
}

export type InputMode = 'file' | 'url';

export interface AnalysisState {
  loading: boolean;
  error: string | null;
  result: SunoPrompt | null;
  rawMarkdown: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { SunoPrompt } from "../types";

const PROMPT_INSTRUCTION = `
You are a master musicologist and prompt engineer for AI music generation.
Analyze the provided audio or music information and output a "Style Prompt" optimized for Suno AI.

Return the response in JSON format matching this schema:
{
  "genre": "comma-separated list of genres and subgenres",
  "vocalStyle": "detailed description of vocals (gender, tone, language, processing)",
  "instruments": "list of primary and secondary instruments and textures",
  "productionStyle": "how it was recorded/mixed (e.g., lo-fi, polished, analog, reverb-drenched)",
  "mood": "emotional keywords",
  "tempo": "speed and rhythmic feel (e.g., mid-tempo, 120bpm, swing feel)"
}
`;

export async function analyzeAudioFile(base64Data: string, mimeType: string): Promise<SunoPrompt> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    contents: {
      parts: [
        { inlineData: { data: base64Data, mimeType } },
        { text: PROMPT_INSTRUCTION }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          genre: { type: Type.STRING },
          vocalStyle: { type: Type.STRING },
          instruments: { type: Type.STRING },
          productionStyle: { type: Type.STRING },
          mood: { type: Type.STRING },
          tempo: { type: Type.STRING },
        },
        required: ["genre", "vocalStyle", "instruments", "productionStyle", "mood", "tempo"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

export async function analyzeMusicUrl(url: string): Promise<SunoPrompt> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze the music at this link: ${url}. ${PROMPT_INSTRUCTION}`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          genre: { type: Type.STRING },
          vocalStyle: { type: Type.STRING },
          instruments: { type: Type.STRING },
          productionStyle: { type: Type.STRING },
          mood: { type: Type.STRING },
          tempo: { type: Type.STRING },
        },
        required: ["genre", "vocalStyle", "instruments", "productionStyle", "mood", "tempo"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

import React, { useState, useCallback } from 'react';
