              onClick={handleProcess}
              disabled={state.loading || (mode === 'file' ? !file : !url)}
              className="w-full mt-4 bg-[#ccff00] text-black font-bold py-4 hover:bg-white active:scale-95 transition-all disabled:opacity-50 disabled:grayscale uppercase tracking-tighter text-lg relative overflow-hidden"
            >
              {state.loading ? (
                <span className="flex items-center justify-center gap-2">
                  <Loader2 className="animate-spin" /> 
                  <span className="animate-pulse">THINKING...</span>
                </span>
              ) : "DECONSTRUCT"}
            </button>
          </div>

          {state.error && (
            <div className="p-4 bg-red-900/20 border border-red-500 text-red-400 text-xs uppercase animate-pulse font-mono">
              ERROR_LOG: {state.error}
            </div>
          )}
        </section>

        {/* Right: Output Panel */}
        <section className="lg:col-span-7">
          <div className="glass h-full min-h-[500px] flex flex-col relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 flex gap-2 z-20">
              {state.result && (
                <>
                  <button onClick={copyToClipboard} className="p-2 bg-gray-800 hover:bg-[#ccff00] hover:text-black transition-colors rounded-sm" title="Copy Markdown">
                    <Copy className="w-4 h-4" />
                  </button>
                  <button onClick={downloadMarkdown} className="p-2 bg-gray-800 hover:bg-[#ccff00] hover:text-black transition-colors rounded-sm" title="Download .md">
                    <Download className="w-4 h-4" />
                  </button>
                </>
              )}
            </div>

            <div className="flex-1 p-8 font-mono text-sm relative z-10">
              {!state.result && !state.loading && (
                <div className="h-full flex flex-col items-center justify-center text-gray-600 text-center space-y-4 opacity-50">
                  <div className="relative">
                    <RefreshCcw className="w-16 h-16 animate-spin-slow text-gray-700" />
                    <Zap className="w-6 h-6 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-gray-500" />
                  </div>
                  <p className="uppercase tracking-[0.2em]">Awaiting Input Signal</p>
                </div>
              )}

              {state.loading && (
                <div className="h-full flex flex-col items-center justify-center space-y-6">
                  <div className="w-full max-w-xs space-y-2">
                    <div className="flex justify-between text-[10px] text-[#ccff00] uppercase tracking-widest">
                       <span>Analyzing</span>
                       <span className="animate-pulse">...</span>
                    </div>
                    <div className="h-1 bg-gray-800 w-full overflow-hidden">
                       <div className="h-full bg-[#ccff00] animate-indeterminate-bar"></div>
                    </div>
                    <div className="text-xs text-gray-500 font-mono text-center pt-2">
                      Accessing Gemini 3 Pro Neural Network...<br/>
                      Running Web Search...<br/>
                      Deconstructing Audio Waveforms...
                    </div>
                  </div>
                </div>
              )}

              {state.result && (
                <div className="space-y-6 overflow-y-auto max-h-[60vh] pr-4 scrollbar-thin">
                  <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
                    <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Genre</label>
                    <p className="text-white text-lg font-bold">{state.result.genre}</p>
                  </div>
                  <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 delay-100">
                    <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Vocal_Style</label>
                    <p className="text-gray-300">{state.result.vocalStyle}</p>
                  </div>
                  <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 delay-200">
                    <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Instrumentation</label>
                    <p className="text-gray-300">{state.result.instruments}</p>
                  </div>
                  <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 delay-300">
                    <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Production</label>
                    <p className="text-gray-300 italic border-l-2 border-gray-700 pl-3">{state.result.productionStyle}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 delay-400">
                      <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Mood</label>
                      <p className="text-gray-300">{state.result.mood}</p>
                    </div>
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 delay-500">
                      <label className="text-[#ccff00] text-[10px] block mb-1 uppercase tracking-widest">/ Tempo</label>
                      <p className="text-gray-300">{state.result.tempo}</p>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Visualizer Footer Deco */}
            <div className="h-1 bg-gray-900 flex gap-px p-px mt-auto">
               {Array.from({length: 60}).map((_, i) => (
                 <div key={i} className={`flex-1 transition-all duration-100 ${state.loading ? 'bg-[#ccff00]' : 'bg-gray-800'}`}
                      style={{ 
                        height: state.loading ? `${Math.random() * 100}%` : `${20 + Math.random() * 30}%`,
                        opacity: state.loading ? 0.8 : 0.3
                      }}></div>
               ))}
            </div>
          </div>
        </section>
      </main>

      {/* Decorative Elements */}
      <footer className="w-full max-w-4xl mt-auto pt-12 pb-4 flex justify-between items-end border-t border-gray-900 text-[10px] text-gray-700 font-mono tracking-widest relative z-10">
        <div>
          CORE_ENGINE: GEMINI_3.1_PRO_PREVIEW<br/>
          MODULE: THINKING_MODE_ENABLED
        </div>
        <div className="text-right">
          (C) 2024 VIRTUAL_LABS<br/>
          ALL_RIGHTS_REVERSED
        </div>
      </footer>

      <style>{`
        @keyframes indeterminate-bar {
          0% { transform: translateX(-100%); }
          50% { transform: translateX(50%); }
          100% { transform: translateX(200%); }
        }
        .animate-indeterminate-bar {
          animation: indeterminate-bar 1.5s infinite linear;
        }
      `}</style>
    </div>
  );
}
